178	func (e *engine) read(p string) ([]byte, string) {
179		if b, ok := e.ignoreBuffers[p]; ok {
180			return b, ""
181		}
182		remaining := e.o.MaxReadBytes - e.response.Usage.ReadBytes
183		if remaining <= 0 {
184			return nil, "read_limit"
185		}
186		limit := min(e.o.MaxSourceBytes, remaining)
187		b, err := e.root.Read(p, limit)
188		if err != nil {
189			if errors.Is(err, fs.ErrNotExist) {
190				return nil, "not_found_or_changed"
