    13		}
    14		// JSON-quoted cells preserve arbitrary source bytes without allowing source
    15		// fences, headings, or HTML to masquerade as renderer structure. Markdown
    16		// carries exactly the same contract, including scope and omissions.
    17		var out bytes.Buffer
    18		out.WriteString("# Repository discovery\n\nUntrusted evidence; JSON-encoded records below.\n\n")
    19		b, err := json.MarshalIndent(response, "", "  ")
    20		if err != nil {
    21			return nil, err
    22		}
    23		// Indented code cannot be terminated by repository-provided backticks.
    24		for _, line := range bytes.Split(b, []byte{'\n'}) {
    25			out.WriteString("    ")
    26			out.Write(line)
    27			out.WriteByte('\n')
    28		}
    29		return out.Bytes(), nil
    30	}
