316	func candidate(p string) string {
317		name := strings.ToLower(path.Base(p))
318		if strings.HasPrefix(name, "readme") || strings.HasSuffix(name, ".md") {
319			return "documentation"
320		}
321		switch path.Ext(name) {
322		case ".yaml", ".yml", ".toml", ".json", ".ini", ".cfg":
323			return "configuration"
324		}
325		switch name {
326		case "go.mod", "go.sum", "makefile", "dockerfile":
327			return "configuration"
328		}
329		return ""
330	}
